#!/usr/bin/env node
// Bundles migrations/sqlite/*.sql (generated by `drizzle-kit generate`) into
// src/migrations.generated.ts so every runtime (worker, Node, native) gets them without file I/O.
// Usage: node scripts/bundle-migrations.mjs [--check]
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const pkg = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const dir = path.join(pkg, 'migrations/sqlite');
const out = path.join(pkg, 'src/migrations.generated.ts');

const files = readdirSync(dir)
  .filter((f) => /^\d{4}_.+\.sql$/.test(f))
  .sort();

const migrations = files.map((file) => {
  const sql = readFileSync(path.join(dir, file), 'utf8').replaceAll('\r\n', '\n');
  return {
    version: Number(file.slice(0, 4)) + 1,
    name: file.replace(/\.sql$/, ''),
    statements: sql
      .split('--> statement-breakpoint')
      .map((s) => s.trim())
      .filter(Boolean),
  };
});

const content = `// GENERATED by scripts/bundle-migrations.mjs from migrations/sqlite/*.sql. Do not edit.
import type { Migration } from './migrator';

export const SQLITE_MIGRATIONS: readonly Migration[] = ${JSON.stringify(migrations, null, 2)};
`;

if (process.argv.includes('--check')) {
  const current = readFileSync(out, 'utf8').replaceAll('\r\n', '\n');
  if (current !== content) {
    console.error(
      'migrations.generated.ts is out of date. Run: pnpm --filter @budget/db db:generate',
    );
    process.exit(1);
  }
  console.log('migrations.generated.ts is up to date');
} else {
  writeFileSync(out, content);
  console.log(`bundled ${migrations.length} migration(s) into ${path.relative(pkg, out)}`);
}
